import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Kernel source for 3D average pooling (naive window mean)
avgpool_kernel = """
__global__ void avgpool_3d_kernel(const float* input, const int ksize, float* output, int B, int C, int D, int H, int W) {
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < B * C * D * H * W) {
        // Decode linear index to batch, channel, depth, height, width
        const int N = C * D * H * W;          // elements per channel
        int b = idx / N;
        const int rem1 = idx % N;

        const int M = D * H * W;              // elements per (depth,height,width)
        int c = rem1 / M;
        const int rem2 = rem1 % M;

        const int P = H * W;                  // height*width
        int d = rem2 / P;
        const int rem3 = rem2 % P;

        int h = rem3 / W;
        int w = rem3 % W;

        float sum = 0.0f;
        const int half = ksize / 2; // integer division, works for odd ksize
        for (int di = -half; di <= half; ++di) {
            int d0 = d + di;
            if (d0 < 0 || d0 >= D) continue;
            for (int hi = -half; hi <= half; ++hi) {
                int h0 = h + hi;
                if (h0 < 0 || h0 >= H) continue;
                for (int wi = -half; wi <= half; ++wi) {
                    int w0 = w + wi;
                    if (w0 < 0 || w0 >= W) continue;
                    sum += input[(b * C + c) * D * H * W + d0 * H * W + h0 * W + w0];
                }
            }
        }
        float count = ksize * ksize * ksize; // number of elements in the window
        output[idx] = sum / (count);
    }
}
"""

# Wrapper function source for avgpool_cuda
avgpool_cuda_source = """
torch::Tensor avgpool_cuda(torch::Tensor input) {
    auto B = input.size(0);
    auto C = input.size(1);
    auto D = input.size(2);
    auto H = input.size(3);
    auto W = input.size(4);

    const int ksize = 3;
    auto out = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (B * C * D * H * W + block_size - 1) / block_size;

    avgpool_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        ksize,
        out.data_ptr<float>(),
        B, C, D, H, W
    );

    return out;
}
"""

# Load the custom CUDA operator for 3D average pooling
avgpool_cuda = load_inline(
    name="avgpool_cuda",
    cpp_sources=("torch::Tensor avgpool_cuda(torch::Tensor input);"),
    cuda_sources=avgpool_cuda_source,
    functions=["avgpool_cuda"],
    verbose=True,
)

class ModelNew(nn.Module):
    def __init__(self, kernel_size: int = 3, stride: int = None, padding: int = 0):
        super().__init__()
        self.avg_pool_cuda = avgpool_cuda

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.avg_pool_cuda(x)
